// components/StreakCelebration.tsx
import React, { useEffect, useMemo, useRef } from 'react';
import { Modal, View, Text, StyleSheet, Animated, Dimensions, Pressable, Easing } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Speech from 'expo-speech';
import { useAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { theme } from '@/src/theme';
import { getPaletteSnapshot, subscribeTheme, type Palette } from "@/src/theme";

const { width: SCREEN_W, height: SCREEN_H } = Dimensions.get('window');

// Loud celebration fanfare (generated by scripts/generate-streak-fanfare.js).
// Loops for as long as the popup is open and stops the moment it is closed.
const FANFARE_SOURCE = require('../../assets/sounds/streak-fanfare.wav');

const FLOWER_EMOJIS = ['🌸', '🌼', '🌷', '💐', '🌻', '✨'];
const CONGRATS_LINES = [
    "Streak complete! You're on fire.",
    'Another day, another streak. Amazing work!',
    'Goal smashed! Keep that streak alive.',
    'You showed up today. Nicely done.',
    'Streak secured! See you tomorrow.',
];

type Particle = {
    id: number;
    left: number;
    emoji: string;
    delay: number;
    duration: number;
    driftX: number;
    size: number;
    rotateTo: string;
};

function buildParticles(seed: number): Particle[] {
    const rand = (min: number, max: number) => min + Math.random() * (max - min);
    return Array.from({ length: 22 }).map((_, i) => ({
        id: seed * 1000 + i,
        left: rand(0, Math.max(0, SCREEN_W - 28)),
        emoji: FLOWER_EMOJIS[Math.floor(Math.random() * FLOWER_EMOJIS.length)],
        delay: rand(0, 500),
        duration: rand(2200, 3600),
        driftX: rand(-40, 40),
        size: rand(18, 30),
        rotateTo: `${Math.round(rand(-140, 140))}deg`,
    }));
}

type Props = {
    visible: boolean;
    streak?: number;
    onDismiss: () => void;
};

/**
 * Dancing cartoon duo rendered with pure RN Animated (no external assets).
 * Two emoji dancers bounce out of phase while the whole pair sways side to
 * side, with music notes floating up around them — runs for as long as the
 * celebration popup is open.
 */
function DancingCartoon() {
    const bounceA = useRef(new Animated.Value(0)).current;
    const bounceB = useRef(new Animated.Value(0)).current;
    const sway = useRef(new Animated.Value(0)).current;
    const noteL = useRef(new Animated.Value(0)).current;
    const noteR = useRef(new Animated.Value(0)).current;

    useEffect(() => {
        const bounceLoop = (v: Animated.Value, duration: number) =>
            Animated.loop(
                Animated.sequence([
                    Animated.timing(v, { toValue: 1, duration, easing: Easing.out(Easing.quad), useNativeDriver: true }),
                    Animated.timing(v, { toValue: 0, duration, easing: Easing.in(Easing.quad), useNativeDriver: true }),
                ])
            );

        const floatLoop = (v: Animated.Value, duration: number, delay: number) =>
            Animated.loop(
                Animated.sequence([
                    Animated.delay(delay),
                    Animated.timing(v, { toValue: 1, duration, easing: Easing.out(Easing.quad), useNativeDriver: true }),
                ])
            );

        const anims: Animated.CompositeAnimation[] = [
            bounceLoop(bounceA, 280),
            // Phase-offset the second dancer so they alternate, like a real duo.
            Animated.sequence([Animated.delay(140), bounceLoop(bounceB, 280)]),
            Animated.loop(
                Animated.sequence([
                    Animated.timing(sway, { toValue: 1, duration: 560, easing: Easing.inOut(Easing.quad), useNativeDriver: true }),
                    Animated.timing(sway, { toValue: 0, duration: 560, easing: Easing.inOut(Easing.quad), useNativeDriver: true }),
                ])
            ),
            floatLoop(noteL, 1400, 0),
            floatLoop(noteR, 1400, 700),
        ];
        anims.forEach((a) => a.start());
        return () => {
            anims.forEach((a) => a.stop());
        };
    }, [bounceA, bounceB, sway, noteL, noteR]);

    const yA = bounceA.interpolate({ inputRange: [0, 1], outputRange: [0, -26] });
    const yB = bounceB.interpolate({ inputRange: [0, 1], outputRange: [0, -26] });
    const swayRot = sway.interpolate({ inputRange: [0, 1], outputRange: ['-9deg', '9deg'] });
    const nL = noteL.interpolate({ inputRange: [0, 1], outputRange: [0, -72] });
    const nR = noteR.interpolate({ inputRange: [0, 1], outputRange: [0, -72] });
    const oL = noteL.interpolate({ inputRange: [0, 0.25, 1], outputRange: [0, 1, 0] });
    const oR = noteR.interpolate({ inputRange: [0, 0.25, 1], outputRange: [0, 1, 0] });

    return (
        <View style={styles.danceStage} pointerEvents="none">
            <Animated.Text style={[styles.note, { left: -38, transform: [{ translateY: nL }], opacity: oL }]}>🎵</Animated.Text>
            <Animated.Text style={[styles.note, { right: -38, transform: [{ translateY: nR }], opacity: oR }]}>🎶</Animated.Text>
            <Animated.View style={{ transform: [{ rotate: swayRot }] }}>
                <View style={styles.danceRow}>
                    <Animated.Text style={[styles.dancer, { transform: [{ translateY: yA }] }]}>💃</Animated.Text>
                    <Animated.Text style={[styles.dancer, styles.dancerMain, { transform: [{ translateY: yB }] }]}>🕺</Animated.Text>
                </View>
            </Animated.View>
        </View>
    );
}

export function StreakCelebration({ visible, streak, onDismiss }: Props) {
    const seedRef = useRef(0);
    const particles = useMemo(() => {
        if (!visible) return [];
        seedRef.current += 1;
        return buildParticles(seedRef.current);
    }, [visible]);

    const anims = useRef<Animated.Value[]>([]);
    const bannerScale = useRef(new Animated.Value(0)).current;

    // Loud looping background fanfare — plays only while the popup is open
    // and is paused the instant the user closes it.
    const player = useAudioPlayer(FANFARE_SOURCE);

    useEffect(() => {
        if (!visible) {
            player.pause();
            return;
        }

        (async () => {
            try {
                await setAudioModeAsync({
                    playsInSilentMode: true,
                    interruptionMode: 'duckOthers',
                });
            } catch {
                // Audio mode is best-effort; playback still works without it.
            }
        })();

        player.loop = true;
        player.volume = 1; // max device volume for the celebration
        Promise.resolve(player.seekTo(0)).catch(() => { });
        player.play();

        return () => {
            player.pause();
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [visible, player]);

    useEffect(() => {
        if (!visible) return;

        anims.current = particles.map(() => new Animated.Value(0));
        // Loop each flower so they keep popping for as long as the popup is
        // open (the popup no longer auto-dismisses).
        const fall = particles.map((p, i) =>
            Animated.loop(
                Animated.sequence([
                    Animated.delay(p.delay),
                    Animated.timing(anims.current[i], {
                        toValue: 1,
                        duration: p.duration,
                        easing: Easing.linear,
                        useNativeDriver: true,
                    }),
                ])
            )
        );
        const fallAnim = Animated.parallel(fall);
        fallAnim.start();

        bannerScale.setValue(0);
        const bannerAnim = Animated.spring(bannerScale, {
            toValue: 1,
            tension: 120,
            friction: 8,
            useNativeDriver: true,
        });
        bannerAnim.start();

        // Spoken congratulations on top of the fanfare (kept from before).
        const line = CONGRATS_LINES[Math.floor(Math.random() * CONGRATS_LINES.length)];
        Speech.stop();
        Speech.speak(line, { rate: 1, pitch: 1.1 });

        // NOTE: no auto-dismiss timer — the popup stays open (with the music
        // and dancing cartoon running) until the user closes it themselves.
        return () => {
            fallAnim.stop();
            bannerAnim.stop();
            anims.current.forEach((a) => {
                a.stopAnimation();
                a.setValue(0);
            });
            Speech.stop();
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [visible]);

    if (!visible) return null;

    return (
        <Modal visible={visible} transparent animationType="fade" onRequestClose={onDismiss}>
            {/* Deliberately NOT pressable-to-dismiss: the popup only closes
                when the user taps the "Nice!" button (or Android back). */}
            <View style={styles.backdrop}>
                {particles.map((p, i) => {
                    const anim = anims.current[i];
                    if (!anim) return null;
                    const translateY = anim.interpolate({ inputRange: [0, 1], outputRange: [-40, SCREEN_H + 40] });
                    const translateX = anim.interpolate({ inputRange: [0, 1], outputRange: [0, p.driftX] });
                    const rotate = anim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', p.rotateTo] });
                    const opacity = anim.interpolate({ inputRange: [0, 0.85, 1], outputRange: [1, 1, 0] });
                    return (
                        <Animated.Text
                            key={p.id}
                            style={[
                                styles.particle,
                                {
                                    left: p.left,
                                    fontSize: p.size,
                                    opacity,
                                    transform: [{ translateY }, { translateX }, { rotate }],
                                },
                            ]}
                        >
                            {p.emoji}
                        </Animated.Text>
                    );
                })}

                <Animated.View style={[styles.banner, { transform: [{ scale: bannerScale }] }]}>
                    <Ionicons name="flame" size={28} color={theme.warning} />
                    <Text style={styles.bannerTitle}>Streak complete!</Text>
                    {typeof streak === 'number' && (
                        <Text style={styles.bannerSub}>{streak} day{streak === 1 ? '' : 's'} strong 🔥</Text>
                    )}
                    <Pressable style={styles.dismissBtn} onPress={onDismiss} testID="streak-celebration-dismiss">
                        <Text style={styles.dismissTxt}>Nice!</Text>
                    </Pressable>
                    <Text style={styles.dismissHint}>Tap “Nice!” to close</Text>
                </Animated.View>

                <DancingCartoon />
            </View>
        </Modal>
    );
}

const createStyles = (t: Palette) => StyleSheet.create({
    backdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.25)' },
    particle: { position: 'absolute', top: 0 },
    banner: {
        position: 'absolute',
        top: '20%',
        alignSelf: 'center',
        backgroundColor: t.surfaceSecondary,
        borderRadius: 20,
        paddingHorizontal: 28,
        paddingVertical: 22,
        alignItems: 'center',
        gap: 6,
        shadowColor: '#000',
        shadowOpacity: 0.2,
        shadowRadius: 16,
        shadowOffset: { width: 0, height: 8 },
        elevation: 8,
    },
    bannerTitle: { fontSize: 18, fontWeight: '800', color: t.onSurface, marginTop: 4 },
    bannerSub: { fontSize: 13, color: t.onSurfaceMuted },
    dismissBtn: {
        marginTop: 10,
        backgroundColor: t.brandPrimary,
        paddingHorizontal: 20,
        paddingVertical: 8,
        borderRadius: 999,
    },
    dismissTxt: { color: t.onBrandPrimary, fontWeight: '700' },
    dismissHint: { fontSize: 11, color: t.onSurfaceMuted, marginTop: 2 },
    danceStage: {
        position: 'absolute',
        top: '52%',
        alignSelf: 'center',
        alignItems: 'center',
        justifyContent: 'center',
    },
    danceRow: { flexDirection: 'row', alignItems: 'flex-end', gap: 10 },
    dancer: { fontSize: 52 },
    dancerMain: { fontSize: 64 },
    note: {
        position: 'absolute',
        top: -10,
        fontSize: 26,
    },
});

// Rebuild the module styles whenever the active palette changes so
// every consumer (including helper components outside the screen
// function) picks up light/dark without prop drilling.
let styles = createStyles(getPaletteSnapshot());
subscribeTheme(() => {
    styles = createStyles(getPaletteSnapshot());
});